#include <stdio.h>

#define N 8

/* 带哨兵的顺序查找：a[0] 留给哨兵，数据存 a[1..n] */
static int seqSearch(int a[], int n, int key)
{
    int i = n;
    a[0] = key;              /* 设哨兵，免去越界判断 */
    while (a[i] != key)
        i--;
    return i;                /* 返回 0 表示查找失败 */
}

int main(void)
{
    int a[N + 1] = {0, 34, 12, 56, 7, 45, 23, 89, 16};
    int keys[3] = {45, 34, 100};
    int i;

    for (i = 0; i < 3; i++) {
        int pos = seqSearch(a, N, keys[i]);
        if (pos == 0)
            printf("key=%d not found\n", keys[i]);
        else
            printf("key=%d found at %d\n", keys[i], pos);
    }
    return 0;
}

#include <stdio.h>

#define N 11

/* 折半查找：返回下标，*cmp 记录比较次数；失败返回 -1 */
static int binSearch(const int a[], int n, int key, int *cmp)
{
    int low = 0, high = n - 1, mid;
    *cmp = 0;
    while (low <= high) {
        mid = low + (high - low) / 2;
        (*cmp)++;
        if (a[mid] == key) return mid;
        if (a[mid] > key) high = mid - 1;
        else              low  = mid + 1;
    }
    return -1;
}

int main(void)
{
    int a[N] = {7, 12, 16, 23, 34, 45, 56, 67, 78, 89, 96};
    int keys[3] = {7, 45, 50};
    int i, cmp;

    for (i = 0; i < 3; i++) {
        int pos = binSearch(a, N, keys[i], &cmp);
        if (pos < 0)
            printf("key=%d not found, cmp=%d\n", keys[i], cmp);
        else
            printf("key=%d found at %d, cmp=%d\n", keys[i], pos, cmp);
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef struct BSTNode {
    int key;
    struct BSTNode *lchild, *rchild;
} BSTNode, *BSTree;

/* 递归插入：成功返回 1，关键字已存在或内存不足返回 0 */
static int bstInsert(BSTree *t, int key)
{
    BSTNode *p;
    if (*t == NULL) {
        p = (BSTNode *)malloc(sizeof(BSTNode));
        if (p == NULL) return 0;
        p->key = key;
        p->lchild = p->rchild = NULL;
        *t = p;
        return 1;
    }
    if (key == (*t)->key)  return 0;
    if (key < (*t)->key)   return bstInsert(&(*t)->lchild, key);
    return bstInsert(&(*t)->rchild, key);
}

/* 中序遍历：应输出递增序列 */
static void inOrder(const BSTree t)
{
    if (t == NULL) return;
    inOrder(t->lchild);
    printf("%d ", t->key);
    inOrder(t->rchild);
}

static int bstSearch(const BSTree t, int key)
{
    if (t == NULL)        return 0;
    if (t->key == key)    return 1;
    if (key < t->key)     return bstSearch(t->lchild, key);
    return bstSearch(t->rchild, key);
}

static void freeTree(BSTree t)
{
    if (t == NULL) return;
    freeTree(t->lchild);
    freeTree(t->rchild);
    free(t);
}

int main(void)
{
    BSTree t = NULL;
    int keys[7] = {45, 23, 67, 12, 34, 56, 78};
    int i;

    for (i = 0; i < 7; i++)
        bstInsert(&t, keys[i]);

    printf("inOrder: ");
    inOrder(t);
    printf("\nsearch 34: %d\n", bstSearch(t, 34));
    printf("search 50: %d\n", bstSearch(t, 50));

    freeTree(t);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef struct BSTNode {
    int key;
    struct BSTNode *lchild, *rchild;
} BSTNode, *BSTree;

static int bstInsert(BSTree *t, int key)
{
    BSTNode *p;
    if (*t == NULL) {
        p = (BSTNode *)malloc(sizeof(BSTNode));
        if (p == NULL) return 0;
        p->key = key;
        p->lchild = p->rchild = NULL;
        *t = p;
        return 1;
    }
    if (key == (*t)->key) return 0;
    if (key < (*t)->key)  return bstInsert(&(*t)->lchild, key);
    return bstInsert(&(*t)->rchild, key);
}

/* 递归删除关键字为 key 的结点，返回子树新根 */
static BSTree bstDelete(BSTree t, int key)
{
    BSTree p;
    if (t == NULL) return NULL;
    if (key < t->key) {
        t->lchild = bstDelete(t->lchild, key);
    } else if (key > t->key) {
        t->rchild = bstDelete(t->rchild, key);
    } else {                          /* 找到被删结点 */
        if (t->lchild == NULL) {      /* 叶子 或 只有右子树 */
            p = t->rchild;
            free(t);
            return p;
        }
        if (t->rchild == NULL) {      /* 只有左子树 */
            p = t->lchild;
            free(t);
            return p;
        }
        p = t->lchild;                /* 双子树：找中序前驱 */
        while (p->rchild != NULL) p = p->rchild;
        t->key = p->key;              /* 前驱关键字顶替 */
        t->lchild = bstDelete(t->lchild, p->key);
    }
    return t;
}

static void inOrder(const BSTree t)
{
    if (t == NULL) return;
    inOrder(t->lchild);
    printf("%d ", t->key);
    inOrder(t->rchild);
}

static void freeTree(BSTree t)
{
    if (t == NULL) return;
    freeTree(t->lchild);
    freeTree(t->rchild);
    free(t);
}

int main(void)
{
    BSTree t = NULL;
    int keys[8] = {45, 23, 67, 12, 34, 56, 78, 30};
    int i;

    for (i = 0; i < 8; i++)
        bstInsert(&t, keys[i]);

    printf("before:  "); inOrder(t); printf("\n");
    t = bstDelete(t, 12);             /* 叶子 */
    printf("del 12:  "); inOrder(t); printf("\n");
    t = bstDelete(t, 23);             /* 只剩右子树 */
    printf("del 23:  "); inOrder(t); printf("\n");
    t = bstDelete(t, 45);             /* 双子树，用前驱 34 顶替 */
    printf("del 45:  "); inOrder(t); printf("\n");

    freeTree(t);
    return 0;
}

#include <stdio.h>

#define M 13
#define P 13
#define EMPTY -1

int main(void)
{
    int table[M];
    int keys[8] = {19, 14, 23, 1, 68, 20, 84, 27};
    int i, j;

    for (i = 0; i < M; i++) table[i] = EMPTY;

    for (i = 0; i < 8; i++) {
        int h = keys[i] % P;          /* 除留余数 */
        while (table[h] != EMPTY)     /* 冲突则线性探测下一格 */
            h = (h + 1) % M;
        table[h] = keys[i];
    }

    printf("index:");
    for (j = 0; j < M; j++) printf("%4d", j);
    printf("\nvalue:");
    for (j = 0; j < M; j++) {
        if (table[j] == EMPTY) printf("%4s", "-");
        else                   printf("%4d", table[j]);
    }
    printf("\n");
    return 0;
}

#include <stdio.h>

#define M 13
#define P 13
#define EMPTY -1

int main(void)
{
    int table[M];
    int keys[8] = {19, 14, 23, 1, 68, 20, 84, 27};
    int queries[3] = {27, 84, 19};
    int i;

    for (i = 0; i < M; i++) table[i] = EMPTY;
    for (i = 0; i < 8; i++) {
        int h = keys[i] % P;
        while (table[h] != EMPTY) h = (h + 1) % M;
        table[h] = keys[i];
    }

    for (i = 0; i < 3; i++) {
        int key = queries[i];
        int h = key % P, cmp = 0;
        while (table[h] != EMPTY && cmp < M) {
            cmp++;
            if (table[h] == key) {
                printf("key=%d found at %d, cmp=%d\n", key, h, cmp);
                break;
            }
            h = (h + 1) % M;
        }
        if (table[h] == EMPTY)
            printf("key=%d not found, cmp=%d\n", key, cmp);
    }
    return 0;
}
